export type ReplayMode = "timestamp" | "tickNumber" | "eventId";

export interface ReplayTarget {
  readonly mode:  ReplayMode;
  readonly value: number;
}

export interface ReplayResult {
  readonly ok:              boolean;
  readonly stateAt:         unknown;   // état reconstitué
  readonly eventsReplayed:  number;
  readonly stoppedAt:       number;    // tick ou timestamp d'arrêt
  readonly failedAt?:       number;    // tick fautif si erreur
  readonly failedTemplate?: number;    // template fautif si erreur
  readonly reason?:         string;
}

export function canReplay(log: readonly unknown[]): boolean {
  return log.length > 0;
}

