#[derive(Debug, Clone, Copy)]
pub enum ReplayMode { Timestamp, TickNumber, EventId }

#[derive(Debug, Clone)]
pub struct ReplayTarget {
    pub mode:  ReplayMode,
    pub value: u64,
}

#[derive(Debug)]
pub struct ReplayResult {
    pub ok:               bool,
    pub events_replayed:  usize,
    pub stopped_at:       u64,
    pub failed_at:        Option<u32>,    // tick fautif
    pub failed_template:  Option<u32>,    // template fautif
    pub reason:           Option<String>,
}

/// CanReplay — capacité déclarée
pub fn can_replay(log: &[SystemEvent]) -> bool {
    !log.is_empty()
}
